def collate_facility_types(params, valid_facility_types) do
  {facility_type_params, non_facility_type_params} = params |> Map.split(valid_facility_types)

  Map.merge(non_facility_type_params, %{
    "facility_types" => input_to_facility_types(facility_type_params, valid_facility_types)
  })
end

def by_departure_extended_time(
      %TripInfo{departure_extended_time: departure_extended_time_a},
      %TripInfo{departure_extended_time: departure_extended_time_b}
    ) do
  ExtendedTime.compare(departure_extended_time_a, departure_extended_time_b) in [:lt, :eq]
end

def interleave_schedule_trips(weekday_schedules, weekend_schedules) do
  weekday_schedules
  |> Map.new(fn {key, _} ->
    {key, merge_and_sort_trips(weekday_schedules[key], weekend_schedules[key])}
  end)
end

