  module.table_info().name
  |> ExAws.Dynamo.get_item(matching)
  |> request()
  |> case do
    {:ok, empty} when empty == %{} -> {:error, :not_found}
    {:ok, %{} = item} -> {:ok, decode(item, module)}
    {:error, reason} -> {:error, reason}
  end
end
