  case request(ExAws.Dynamo.get_item(table, matching)) do
    {:ok, empty} when empty == %{} -> {:error, :not_found}
    {:ok, %{} = item} -> {:ok, item}
    {:error, reason} -> {:error, reason}
  end
end

