def pattern_for_destination({stop, line, headsign}, typical_patterns) do
  Enum.find(typical_patterns, fn %RoutePattern{
                                   headsign: pattern_headsign,
                                   route: %Route{line: pattern_line},
                                   stops: pattern_stops
