@type Supervisor.on_start_child :: {:ok, child}
| {:ok, child, info :: term}
| {:error, {:already_started, child} | :already_present | term}

definition:
def activity_types do
  @activity_types
end

def filter_local(query) do
  from(a in query, where: is_nil(a.domain))
end

def filter_external(query) do
  from(a in query, where: not is_nil(a.domain))
end

def get_member(actor_id, parent_id) do
  case Repo.get_by(Member, actor_id: actor_id, parent_id: parent_id) do
    nil -> {:error, :member_not_found}
    member -> {:ok, member}
  end
end

